          enum:
            - not_run
            - passed
            - failed
            - blocked
        evidence:
          type: array
          items:
            type: string
            pattern: "^[a-z0-9][a-z0-9-]*[a-z0-9]$|^[a-z0-9]$"
    step:
      type: object
      additionalProperties: false
      required:
        - id
        - action
      properties:
        id:
          type: string
          pattern: "^[a-z0-9][a-z0-9-]*[a-z0-9]$|^[a-z0-9]$"
        action:
          type: string
          minLength: 1
        expected:
          type: string
          minLength: 1
        target:
          type: string
          pattern: "^[a-z0-9][a-z0-9-]*[a-z0-9]$|^[a-z0-9]$"
    evidence_entry:
      type: object
      additionalProperties: false
      required:
        - id
